#!/usr/bin/env python3
"""
Synchronize nxt plugin dispatcher macros from runtime plugin metadata.

This script is intended to run on the SBC/DSF host. It reads plugin metadata,
filters plugins tagged as "nxt-plugin", and atomically writes dispatcher
macros under /sys/nxt/plugins.
"""

from __future__ import annotations

import argparse
import hashlib
import json
import re
import sys
import time
from pathlib import Path
from typing import Any, Dict, Iterable, List, Tuple


DISPATCH_FILES = {
    "init": "nxt-plugin-init-dispatch.g",
    "daemon": "nxt-plugin-daemon-dispatch.g",
    "pause": "nxt-plugin-hooks-pause.g",
    "resume": "nxt-plugin-hooks-resume.g",
    "stop": "nxt-plugin-hooks-stop.g",
    "cancel": "nxt-plugin-hooks-cancel.g",
}


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="Generate nxt plugin dispatchers from runtime metadata."
    )
    parser.add_argument(
        "--registry",
        default="/opt/dsf/sd/sys/dwc-plugins.json",
        help="Path to plugin registry JSON (default: %(default)s)",
    )
    parser.add_argument(
        "--sys-root",
        default="/opt/dsf/sd/sys",
        help="Path to /sys root (default: %(default)s)",
    )
    parser.add_argument(
        "--output-dir",
        default="/opt/dsf/sd/sys/nxt/plugins",
        help="Dispatcher output directory (default: %(default)s)",
    )
    parser.add_argument(
        "--once",
        action="store_true",
        help="Run a single sync and exit.",
    )
    parser.add_argument(
        "--interval",
        type=float,
        default=5.0,
        help="Polling interval in seconds when not using --once (default: %(default)s)",
    )
    parser.add_argument(
        "--strict-default",
        action="store_true",
        help="Treat missing entrypoints as strict when failureMode is omitted.",
    )
    return parser.parse_args()


def load_registry(path: Path) -> List[Dict[str, Any]]:
    data = json.loads(path.read_text(encoding="utf-8"))
    if isinstance(data, dict):
        # dwc-plugins.json is usually an object keyed by plugin id.
        return [v for v in data.values() if isinstance(v, dict)]
    if isinstance(data, list):
        return [v for v in data if isinstance(v, dict)]
    raise ValueError("Plugin registry must be a JSON object or array")


def plugin_nxt_meta(plugin: Dict[str, Any]) -> Dict[str, Any]:
    data = plugin.get("data")
    if not isinstance(data, dict):
        return {}
    nxt = data.get("nxt")
    if isinstance(nxt, dict):
        return nxt
    return {}


def is_enabled_nxt_plugin(plugin: Dict[str, Any]) -> bool:
    nxt = plugin_nxt_meta(plugin)
    if nxt.get("tag") != "nxt-plugin":
        return False
    return bool(nxt.get("enabled", True))


def plugin_sort_key(plugin: Dict[str, Any]) -> Tuple[int, str]:
    nxt = plugin_nxt_meta(plugin)
    load_order = nxt.get("loadOrder", 1000)
    try:
        load_order_int = int(load_order)
    except (TypeError, ValueError):
        load_order_int = 1000
    plugin_id = str(plugin.get("id", "zzzz")).lower()
    return (load_order_int, plugin_id)


def sanitize_plugin_id(plugin_id: str) -> str:
    return re.sub(r"[^a-z0-9]+", "_", plugin_id.lower()).strip("_") or "unknown"


def to_rrf_macro_path(raw_path: str) -> str:
    path = raw_path.strip()
    if path.startswith("0:/sys/"):
        return path[len("0:/sys/") :]
    if path.startswith("/sys/"):
        return path[len("/sys/") :]
    return path


def entrypoint_exists(sys_root: Path, macro_path: str) -> bool:
    rel = to_rrf_macro_path(macro_path)
    return (sys_root / rel).is_file()


def header(title: str) -> List[str]:
    return [
        "; Auto-generated by nxt_plugin_registry_sync.py. Do not edit.",
        f"; {title}",
    ]


def build_dispatchers(
    plugins: List[Dict[str, Any]], sys_root: Path, strict_default: bool
) -> Dict[str, str]:
    files: Dict[str, List[str]] = {
        "init": header("nxt plugin init dispatcher"),
        "daemon": header("nxt plugin daemon dispatcher"),
        "pause": header("nxt plugin pause hooks dispatcher"),
        "resume": header("nxt plugin resume hooks dispatcher"),
        "stop": header("nxt plugin stop hooks dispatcher"),
        "cancel": header("nxt plugin cancel hooks dispatcher"),
    }

    def validate_or_error(
        plugin_id: str, failure_mode: str, event_name: str, entrypoint: str
    ) -> bool:
        if entrypoint_exists(sys_root, entrypoint):
            return True
        if failure_mode == "strict":
            raise RuntimeError(
                f"Missing {event_name} entrypoint for {plugin_id}: {entrypoint}"
            )
        print(
            f"warning: Missing {event_name} entrypoint for {plugin_id}: {entrypoint}",
            file=sys.stderr,
        )
        return False

    for plugin in plugins:
        plugin_id = str(plugin.get("id", "unknown"))
        nxt = plugin_nxt_meta(plugin)
        entrypoints = nxt.get("entrypoints", {})
        if not isinstance(entrypoints, dict):
            entrypoints = {}

        failure_mode = str(
            nxt.get("failureMode", "strict" if strict_default else "soft")
        ).lower()
        safe_id = sanitize_plugin_id(plugin_id)

        init_entry = entrypoints.get("init")
        skip_init = bool(nxt.get("skipInitDispatch"))
        feature_flag = str(nxt.get("featureFlag", "")).strip()
        if isinstance(init_entry, str) and init_entry.strip() and not skip_init:
            if validate_or_error(plugin_id, failure_mode, "init", init_entry):
                init_path = to_rrf_macro_path(init_entry)
                if feature_flag:
                    files["init"].extend(
                        [
                            f"if {{ exists(global.{feature_flag}) && global.{feature_flag} }}",
                        ]
                    )
                files["init"].extend(
                    [
                        f"if {{ !exists(global.nxtPluginLoaded_{safe_id}) }}",
                        f"    global nxtPluginLoaded_{safe_id} = false",
                        "",
                        f"if {{ !global.nxtPluginLoaded_{safe_id} }}",
                        f"    M98 P\"{init_path}\"",
                        f"    set global.nxtPluginLoaded_{safe_id} = true",
                        "",
                    ]
                )

        for key in ("daemon", "pause", "resume", "stop", "cancel"):
            event_entry = entrypoints.get(key)
            if not isinstance(event_entry, str) or not event_entry.strip():
                continue
            if not validate_or_error(plugin_id, failure_mode, key, event_entry):
                continue
            event_path = to_rrf_macro_path(event_entry)
            files[key].extend(
                [
                    f"if {{ exists(global.nxtPluginLoaded_{safe_id}) && global.nxtPluginLoaded_{safe_id} }}",
                    f"    M98 P\"{event_path}\"",
                    "",
                ]
            )

    for key, lines in files.items():
        if len(lines) <= 2:
            lines.append("; no plugins tagged nxt-plugin")

    return {k: "\n".join(v).rstrip() + "\n" for k, v in files.items()}


def digest_outputs(outputs: Dict[str, str]) -> str:
    payload = "".join(outputs[name] for name in sorted(outputs.keys()))
    return hashlib.sha256(payload.encode("utf-8")).hexdigest()


def atomic_write(path: Path, content: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_suffix(path.suffix + ".tmp")
    tmp.write_text(content, encoding="utf-8")
    tmp.replace(path)


def run_sync(
    registry_path: Path, sys_root: Path, output_dir: Path, strict_default: bool
) -> bool:
    plugins = load_registry(registry_path)
    nxt_plugins = sorted(
        (p for p in plugins if is_enabled_nxt_plugin(p)),
        key=plugin_sort_key,
    )
    outputs = build_dispatchers(nxt_plugins, sys_root=sys_root, strict_default=strict_default)
    current_digest = digest_outputs(outputs)

    state_path = output_dir / ".nxt-plugin-registry-sync.sha256"
    previous_digest = ""
    if state_path.is_file():
        previous_digest = state_path.read_text(encoding="utf-8").strip()
    if current_digest == previous_digest:
        return False

    for key, filename in DISPATCH_FILES.items():
        atomic_write(output_dir / filename, outputs[key])
    atomic_write(state_path, current_digest + "\n")
    return True


def main() -> int:
    args = parse_args()
    registry_path = Path(args.registry)
    sys_root = Path(args.sys_root)
    output_dir = Path(args.output_dir)

    if args.once:
        changed = run_sync(
            registry_path=registry_path,
            sys_root=sys_root,
            output_dir=output_dir,
            strict_default=bool(args.strict_default),
        )
        if changed:
            print("Dispatchers updated.")
        else:
            print("Dispatchers unchanged.")
        return 0

    while True:
        try:
            changed = run_sync(
                registry_path=registry_path,
                sys_root=sys_root,
                output_dir=output_dir,
                strict_default=bool(args.strict_default),
            )
            if changed:
                print("Dispatchers updated.")
        except Exception as exc:
            print(f"sync error: {exc}", file=sys.stderr)
        time.sleep(args.interval)


if __name__ == "__main__":
    raise SystemExit(main())
